// --- Viewport snapshot for mobile map view ---

/**
 * Yield until the renderer has painted. After `token.update` / moves, PIXI may
 * not rebuild `canvas.primary` until the next frame — capturing immediately
 * can return JPEGs where the actor token still sits on the previous cell.
 */
export async function waitForPresentationFrames(frameCount = 2) {
  let n = Math.max(1, Number(frameCount) || 2);
  while (n-- > 0) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
}

/**
 * MeasuredTemplateObject.shape is filled after the placeable syncs / paints.
 */
export async function finalizeStagedTemplatePlaceable(templateDoc) {
  if (!templateDoc?.id || !canvas?.scene) return templateDoc;
  await waitForPresentationFrames(2);
  let doc = canvas.scene.templates.get(templateDoc.id) ?? templateDoc;
  const placeable = doc.object;
  if (placeable) {
    if (typeof placeable._refreshShape === "function") placeable._refreshShape();
    else if (typeof placeable.refresh === "function") placeable.refresh();
  }
  await waitForPresentationFrames(1);
  return canvas.scene.templates.get(doc.id) ?? doc;
}

/**
 * If shape is still unavailable (gridless / timing): sphere / circle uses center + radius in px.
 */
export function collectTokenIdsInCircleTemplate(templateDoc) {
  const grid = canvas.grid;
  if (!grid || grid.isGridless) return [];
  // Grid-correct radius: the v14 compat `distance` is converted with the default
  // grid, so read the backing Region's shape instead.
  const geo = templateGeometry(templateDoc, regionForTemplate(templateDoc, templateDoc.parent ?? canvas.scene), grid);
  const tx = geo.x;
  const ty = geo.y;
  const radiusPx = geo.radiusPx;
  const r2 = radiusPx * radiusPx;
  const ids = [];
  for (const token of canvas.tokens.placeables) {
    const dx = token.center.x - tx;
    const dy = token.center.y - ty;
    if (dx * dx + dy * dy <= r2) ids.push(token.id);
  }
  return ids;
}

/**
 * Template placement for item.use drawPreview — no canvas document until cast confirms.
 */
export function resolveTemplatePlacementAtCasterToken(user, actor, measuredSpec) {
  const tokenDocs = tokenDocumentsForActorOnScene(actor, canvas.scene);
  const td = tokenDocs[0];
  if (!td) throw new Error("No token on scene for this actor");
  const t = SHAPE_TO_TEMPLATE_TYPE[String(measuredSpec.shape).toLowerCase()] ?? "circle";
  const tokenObj = td.object;
  const center = tokenObj ? tokenObj.center : { x: td.x, y: td.y };
  return {
    t,
    x: center.x,
    y: center.y,
    distance: measuredSpec.size,
    direction: td.rotation ?? 0,
    elevation: td.elevation ?? 0,
    fillColor: user.color ?? "#FF0000"
  };
}

export function resolveItemAreaActivity(item) {
  if (!item?.system) return null;
  for (const activity of iterItemActivities(item.system)) {
    if (!resolveTargetBlockTemplate(activity?.target)) continue;
    if (activity?.uuid) return activity;
    const id = activity?.id ?? activity?._id;
    if (id && typeof item.system.activities?.get === "function") {
      return item.system.activities.get(id) ?? activity;
    }
    return activity;
  }
  return null;
}

export function midiQolApi() {
  return globalThis.MidiQOL ?? game.modules.get("midi-qol")?.api ?? null;
}

/** Mirrors midi-qol getAoETargetType / ignoreSelf / autoTarget for template sync. */
export function midiAoETargetParams(activity) {
  const mqol = midiQolApi();
  let aoEType = "any";
  let ignoreSelf = false;
  if (activity?.target) {
    ignoreSelf = (activity.target.affects?.special ?? "")
      .split(";")
      .some((spec) => spec === "-self");
    const affectsType = activity.target.affects?.type;
    if (affectsType === "ally") aoEType = "ally";
    else if (affectsType === "enemy") aoEType = "enemy";
    const override = activity.midiProperties?.autoTargetType;
    if (override && override !== "any") aoEType = override;
  }
  let autoTarget = mqol?.configSettings?.()?.autoTarget ?? "wallsBlock";
  const action = activity?.midiProperties?.autoTargetAction;
  if (action && action !== "default") autoTarget = action;
  return { ignoreSelf, aoEType, autoTarget };
}

export function applyStagingTemplateFlags(templateData, actor, tokenDoc, item) {
  if (!templateData.flags) templateData.flags = {};
  foundry.utils.setProperty(templateData, `flags.${MODULE_ID}.staging`, true);
  if (item?.id) foundry.utils.setProperty(templateData, `flags.${MODULE_ID}.itemId`, item.id);
  if (tokenDoc?.uuid) {
    foundry.utils.setProperty(templateData, "flags.midi-qol.sourceTokenUuid", tokenDoc.uuid);
  }
  if (actor?.uuid) foundry.utils.setProperty(templateData, "flags.midi-qol.actorUuid", actor.uuid);
}

export function applyCastTemplateFlags(templateData, activity, actor, tokenDoc, item) {
  if (!templateData.flags) templateData.flags = {};
  foundry.utils.setProperty(templateData, `flags.${MODULE_ID}.staging`, false);
  if (activity?.uuid) {
    foundry.utils.setProperty(templateData, "flags.dnd5e.origin", activity.uuid);
    const size = templateData.distance ?? activity.target?.template?.size;
    if (size != null) {
      foundry.utils.setProperty(templateData, "flags.dnd5e.dimensions", { size });
    }
  } else if (item?.uuid) {
    foundry.utils.setProperty(templateData, `flags.${game.system?.id ?? "dnd5e"}.origin`, item.uuid);
  }
  if (item?.id) foundry.utils.setProperty(templateData, `flags.${MODULE_ID}.itemId`, item.id);
  if (tokenDoc?.uuid) {
    foundry.utils.setProperty(templateData, "flags.midi-qol.sourceTokenUuid", tokenDoc.uuid);
  }
  if (actor?.uuid) foundry.utils.setProperty(templateData, "flags.midi-qol.actorUuid", actor.uuid);
  const itemUuid = activity?.item?.uuid ?? item?.uuid;
  if (itemUuid) foundry.utils.setProperty(templateData, "flags.midi-qol.itemUuid", itemUuid);
  if (activity) {
    Hooks.call("dnd5e.preCreateActivityTemplate", activity, templateData);
  }
}

export function resolveActivityFromBridgeTemplate(templateDoc, actor) {
  const bridgeItemId = bridgeFlag(templateDoc, "itemId");
  if (bridgeItemId && actor?.items) {
    const item = actor.items.get(bridgeItemId);
    if (item) return resolveItemAreaActivity(item);
  }
  if (templateDoc?.flags?.dnd5e?.origin) {
    return fromUuidSync(templateDoc.flags.dnd5e.origin);
  }
  return null;
}

/**
 * Sync template area targets via Midi-QOL (walls, disposition, AoE filters).
 * Also mirrors targets to the requesting player for Foundry target rings.
 */
export async function syncTemplateTargetsViaMidiQol(user, templateDoc, activity, actor) {
  if (!user || !templateDoc) return [];

  const working = await finalizeStagedTemplatePlaceable(templateDoc);
  const templateRef = working.object ?? working;

  let resolvedActor = actor ?? null;
  if (!resolvedActor && working.flags?.["midi-qol"]?.actorUuid) {
    resolvedActor = fromUuidSync(working.flags["midi-qol"].actorUuid);
  }
  let resolvedActivity = activity ?? resolveActivityFromBridgeTemplate(working, resolvedActor);
  if (!resolvedActor && resolvedActivity?.actor) {
    resolvedActor = resolvedActivity.actor;
  }

  const { ignoreSelf, aoEType, autoTarget } = midiAoETargetParams(resolvedActivity);
  const mqol = midiQolApi();

  let sourceToken = null;
  const sourceUuid = working.flags?.["midi-qol"]?.sourceTokenUuid;
  if (sourceUuid) {
    const td = fromUuidSync(sourceUuid);
    sourceToken = td?.object ?? td ?? null;
  } else if (resolvedActor && canvas?.scene) {
    sourceToken = tokenDocumentsForActorOnScene(resolvedActor, canvas.scene)[0]?.object ?? null;
  }

  if (!mqol?.computeTargetsFromTemplates) {
    console.warn(`[${MODULE_ID}] syncTemplateTargetsViaMidiQol: midi-qol API unavailable`);
    return [];
  }

  if (autoTarget === "none") {
    applyUserTokenTargets(user, []);
    rememberTemplateTargets(working, []);
    return [];
  }

  const tokens = mqol.computeTargetsFromTemplates(
    [templateRef],
    sourceToken,
    ignoreSelf,
    aoEType,
    autoTarget
  );
  const ids = tokens.map((t) => t.id).filter(Boolean);

  applyUserTokenTargets(user, ids);
  // Record what this template targeted so removing it can un-set exactly these.
  rememberTemplateTargets(working, ids);
  if (typeof mqol.selectTargetsFromTemplates === "function") {
    mqol.selectTargetsFromTemplates([templateRef], sourceToken, ignoreSelf, aoEType, autoTarget);
  }

  return ids;
}

/** DevTools filter: `[MobileBridge:viewport]` */
export const VIEWPORT_LOG_PREFIX = "[MobileBridge:viewport]";

export function rectToStr(r) {
  if (!r) return "null";
  const x = Math.round(r.x ?? 0);
  const y = Math.round(r.y ?? 0);
  const w = Math.round(r.width ?? r.w ?? 0);
  const h = Math.round(r.height ?? r.h ?? 0);
  return `${x},${y},${w},${h}`;
}

/** Fraction of near-black pixels in a canvas region (0..1). */
export function sampleCanvasBlackRatio(canvas, x, y, w, h, maxSamples = 256) {
  if (!canvas?.getContext || w <= 0 || h <= 0) return null;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  const cw = canvas.width;
  const ch = canvas.height;
  if (!cw || !ch) return null;
  const x0 = Math.max(0, Math.min(cw - 1, Math.floor(x)));
  const y0 = Math.max(0, Math.min(ch - 1, Math.floor(y)));
  const rw = Math.max(1, Math.min(cw - x0, Math.ceil(w)));
  const rh = Math.max(1, Math.min(ch - y0, Math.ceil(h)));
  let data;
  try {
    data = ctx.getImageData(x0, y0, rw, rh).data;
  } catch (err) {
    return null;
  }
  const step = Math.max(1, Math.floor(Math.sqrt((rw * rh) / maxSamples)));
  let black = 0;
  let total = 0;
  for (let py = 0; py < rh; py += step) {
    for (let px = 0; px < rw; px += step) {
      const i = (py * rw + px) * 4;
      total++;
      if (data[i] < 12 && data[i + 1] < 12 && data[i + 2] < 12) black++;
    }
  }
  return total > 0 ? black / total : null;
}

export function analyzeViewportCanvas(canvas) {
  const w = canvas?.width ?? 0;
  const h = canvas?.height ?? 0;
  if (!w || !h) {
    return { extractedSize: `${w}x${h}` };
  }
  const qw = Math.max(8, Math.floor(w / 4));
  const qh = Math.max(8, Math.floor(h / 4));
  return {
    extractedSize: `${w}x${h}`,
    blackOverall: sampleCanvasBlackRatio(canvas, 0, 0, w, h),
    blackTopLeft: sampleCanvasBlackRatio(canvas, 0, 0, qw, qh),
    blackTopRight: sampleCanvasBlackRatio(canvas, w - qw, 0, qw, qh),
    blackBottomLeft: sampleCanvasBlackRatio(canvas, 0, h - qh, qw, qh),
    blackBottomRight: sampleCanvasBlackRatio(canvas, w - qw, h - qh, qw, qh)
  };
}

export function collectPrimaryLayerDebug(primary) {
  const bg = primary?.background;
  const rt = primary?.renderTexture;
  return {
    primaryChildCount: primary?.children?.length ?? 0,
    primaryCacheSize: rt ? `${rt.width}x${rt.height}` : "null",
    backgroundPos: bg ? `${Math.round(bg.x)},${Math.round(bg.y)}` : "null",
    backgroundSize: bg ? `${Math.round(bg.width)}x${Math.round(bg.height)}` : "null",
    backgroundVisible: bg?.visible ?? false,
    backgroundTexValid: bg?.texture?.valid ?? false
  };
}

export function logViewportSnapshot(debug) {
  console.log(`${VIEWPORT_LOG_PREFIX}`, debug);
}

/** Scene meshes intersect [rect] in canvas pixel space. */
export function meshIntersectsViewportRect(mesh, rect) {
  if (!mesh?.visible || mesh.renderable === false) return false;
  const w = mesh.width ?? 0;
  const h = mesh.height ?? 0;
  if (!(w > 0 && h > 0)) return false;
  const ax = mesh.anchor?.x ?? 0;
  const ay = mesh.anchor?.y ?? 0;
  const left = (mesh.x ?? 0) - w * ax;
  const top = (mesh.y ?? 0) - h * ay;
  if (left + w < rect.x) return false;
  if (left > rect.x + rect.width) return false;
  if (top + h < rect.y) return false;
  if (top > rect.y + rect.height) return false;
  return true;
}

export function copySpriteMeshToExport(mesh, rect, zIndex = 0) {
  const tex = mesh?.texture;
  if (!tex || tex === PIXI.Texture.EMPTY) return null;
  const sprite = new PIXI.Sprite(tex);
  sprite.anchor.set(mesh.anchor?.x ?? 0, mesh.anchor?.y ?? 0);
  sprite.position.set((mesh.x ?? 0) - rect.x, (mesh.y ?? 0) - rect.y);
  sprite.rotation = mesh.rotation ?? 0;
  sprite.scale.set(mesh.scale?.x ?? 1, mesh.scale?.y ?? 1);
  sprite.width = mesh.width;
  sprite.height = mesh.height;
  sprite.tint = mesh.tint ?? 0xffffff;
  sprite.alpha = mesh.alpha ?? 1;
  sprite.zIndex = zIndex;
  sprite.cullable = false;
  return sprite;
}

/**
 * Build an off-screen container for viewport export.
 * PrimaryCanvasGroup is a screen-sized CachedContainer — rendering it directly for
 * arbitrary crops only captures the GM's current screen. Instead, copy visible
 * primary sprites into crop-local coordinates (same approach as Scene#createThumbnail).
 */
export function buildViewportExportContainer(primary, rect, includeToken = null) {
  const root = new PIXI.Container();
  root.sortableChildren = true;
  root.cullable = false;

  const addLayerMesh = (mesh, zIndex) => {
    if (!meshIntersectsViewportRect(mesh, rect)) return;
    const sprite = copySpriteMeshToExport(mesh, rect, zIndex);
    if (sprite) root.addChild(sprite);
  };

  if (primary.background) {
    addLayerMesh(primary.background, primary.background.sortLayer ?? -Infinity);
  }
  for (const tile of primary.tiles?.values?.() ?? []) {
    addLayerMesh(tile, tile.sortLayer ?? tile.zIndex ?? 500);
  }
  for (const drawing of primary.drawings?.values?.() ?? []) {
    if (!meshIntersectsViewportRect(drawing, rect)) continue;
    const clone = typeof drawing.clone === "function" ? drawing.clone() : null;
    if (!clone) continue;
    clone.position.set((drawing.x ?? 0) - rect.x, (drawing.y ?? 0) - rect.y);
    clone.cullable = false;
    clone.zIndex = drawing.sortLayer ?? drawing.zIndex ?? 600;
    root.addChild(clone);
  }
  for (const [key, token] of primary.tokens?.entries?.() ?? []) {
    // `includeToken` is set for non-GM requesters: tokens they cannot see are not
    // drawn into the picture. An id that cannot be resolved is not drawn either.
    if (includeToken) {
      const id = token.object?.document?.id ?? token.document?.id ?? key;
      if (!includeToken(id)) continue;
    }
    addLayerMesh(token, token.sortLayer ?? token.zIndex ?? 700);
  }
  if (primary.foreground) {
    addLayerMesh(primary.foreground, primary.foreground.sortLayer ?? 1000);
  }

  root.sortChildren();
  return root;
}

/**
 * Render a region of the current scene to a JPEG and return it as base64
 * along with positions of visible tokens (and an optional active template).
 *
 * The crop is specified in grid cells around a center cell. Hex grids are
 * handled by delegating cell math to `canvas.grid.getCenterPoint` /
 * `getShiftedOffset`, so the client does not need to understand hex offsets.
 *
 * `payload.panDirection` lets the client move the camera by one (or `panSteps`)
 * cells without computing hex deltas manually.
 */
export async function captureViewport(user, payload) {
  if (!canvas?.ready || !canvas.scene) {
    return { error: "canvas_not_ready" };
  }

  await waitForPresentationFrames(2);

  const {
    actorId,
    centerGridI = null,
    centerGridJ = null,
    widthCells: rawW = 9,
    heightCells: rawH = 11,
    panDirection = null,
    panSteps: rawPanSteps = 1,
    format: rawFormat = "jpeg",
    quality: rawQ = 0.75,
    maxLongSidePx: rawMaxPx = 1500,
    activeTemplateId = null,
    fullScene: rawFullScene = false
  } = payload ?? {};
  const fullScene = rawFullScene === true;

  const actor = getOwnedActor(user, actorId);
  const scene = canvas.scene;
  const grid = canvas.grid;
  const gridless = !grid || grid.isGridless;
  const gridTypeId = scene?.grid?.type ?? grid?.type ?? null;
  const gridType = detectGridType(grid, scene);

  if (gridless) {
    return {
      error: "gridless",
      gridless: true,
      gridType,
      gridTypeId,
      sceneId: scene.id ?? null,
      sceneName: scene.name ?? null
    };
  }

  // This picture is rendered from the GM tab: no fog, every token. A player on a
  // vision-limited scene must not get it (the map model draws those scenes), and
  // elsewhere gets it without the tokens they cannot see. GMs are unchanged.
  const policy = viewportSnapshotPolicy({
    isGM: !!user?.isGM,
    tokenVision: sceneUsesTokenVision(canvas.visibility?.tokenVision, scene.tokenVision)
  });
  if (!policy.allowed) {
    return { error: policy.reason, sceneId: scene.id ?? null, sceneName: scene.name ?? null };
  }
  let visibleTokenIds = null;
  if (policy.filterTokens) {
    const viewerDoc = actor ? viewerTokenDocFor(actor, scene) : null;
    visibleTokenIds = new Set(
      visibleTokenDocsFor(user, scene, viewerDoc?.id ?? null, viewerVisionFor(viewerDoc)).map((td) => td.id)
    );
  }
  const includeTokenDoc = (td) => snapshotIncludesToken(policy, td, visibleTokenIds);

  const widthCells = Math.max(3, Math.min(32, Number(rawW) || 9));
  const heightCells = Math.max(3, Math.min(32, Number(rawH) || 11));
  const quality = Math.max(0.3, Math.min(0.95, Number(rawQ) || 0.75));
  const maxLongSidePx = Math.max(200, Math.min(4096, Number(rawMaxPx) || 1500));
  const format = rawFormat === "png" ? "png" : "jpeg";
  const mimeType = format === "png" ? "image/png" : "image/jpeg";

  // Accept null/undefined to mean "no explicit center" — the fallback below
  // then uses the player's own token, or the scene center as a last resort.
  const hasI = centerGridI !== null && centerGridI !== undefined;
  const hasJ = centerGridJ !== null && centerGridJ !== undefined;
  let centerI = hasI && Number.isFinite(Number(centerGridI)) ? Number(centerGridI) : null;
  let centerJ = hasJ && Number.isFinite(Number(centerGridJ)) ? Number(centerGridJ) : null;
  if (centerI === null || centerJ === null) {
    const tokenDocs = tokenDocumentsForActorOnScene(actor, scene);
    const td = tokenDocs[0];
    if (td) {
      const off = grid.getOffset({ x: td.x, y: td.y });
      centerI = off.i;
      centerJ = off.j;
    } else {
      const sceneW = scene.width ?? canvas.dimensions?.sceneWidth ?? 0;
      const sceneH = scene.height ?? canvas.dimensions?.sceneHeight ?? 0;
      const off = grid.getOffset({ x: sceneW / 2, y: sceneH / 2 });
      centerI = off.i;
      centerJ = off.j;
    }
  }

  if (!fullScene && panDirection) {
    const dirConst = movementDirectionConstByKey(String(panDirection).toLowerCase());
    if (dirConst !== undefined) {
      const steps = Math.max(1, Math.min(16, Number(rawPanSteps) || 1));
      let off = { i: centerI, j: centerJ };
      for (let s = 0; s < steps; s++) {
        off = grid.getShiftedOffset(off, dirConst);
      }
      centerI = off.i;
      centerJ = off.j;
    }
  }

  const sizeX = grid.sizeX ?? grid.size;
  const sizeY = grid.sizeY ?? grid.size;
  const scenePxW = scene.width ?? canvas.dimensions?.sceneWidth ?? 0;
  const scenePxH = scene.height ?? canvas.dimensions?.sceneHeight ?? 0;

  let pxW;
  let pxH;
  let rect;
  /** Reported grid span / center — full-scene uses scene midpoint for stable metadata. */
  let outWidthCells = widthCells;
  let outHeightCells = heightCells;
  let reportCenterI = centerI;
  let reportCenterJ = centerJ;

  const dim = canvas.dimensions ?? null;
  const sr = dim?.sceneRect;
  /** Scene bounds in canvas pixel space — matches how tokens/`canvas.primary` are positioned (often not (0,0)). */
  let fullSceneRect = null;
  if (sr && Number(sr.width) > 0 && Number(sr.height) > 0) {
    fullSceneRect = sr;
  } else if (scenePxW > 0 && scenePxH > 0) {
    fullSceneRect = new PIXI.Rectangle(0, 0, scenePxW, scenePxH);
  }

  if (fullScene && fullSceneRect) {
    pxW = Math.round(fullSceneRect.width);
    pxH = Math.round(fullSceneRect.height);
    rect = new PIXI.Rectangle(
      Math.round(fullSceneRect.x),
      Math.round(fullSceneRect.y),
      pxW,
      pxH
    );
    outWidthCells = Math.max(3, Math.ceil(pxW / Math.max(1e-6, sizeX)));
    outHeightCells = Math.max(3, Math.ceil(pxH / Math.max(1e-6, sizeY)));
    const cx = fullSceneRect.x + fullSceneRect.width / 2;
    const cy = fullSceneRect.y + fullSceneRect.height / 2;
    const midOff = grid.getOffset({ x: cx, y: cy });
    reportCenterI = midOff.i;
    reportCenterJ = midOff.j;
  } else if (!fullScene) {
    const center = grid.getCenterPoint({ i: centerI, j: centerJ });
    pxW = Math.round(widthCells * sizeX);
    pxH = Math.round(heightCells * sizeY);
    rect = new PIXI.Rectangle(
      Math.round(center.x - pxW / 2),
      Math.round(center.y - pxH / 2),
      pxW,
      pxH
    );
  } else {
    return {
      error: "scene_dimensions_unavailable",
      sceneId: scene.id ?? null,
      sceneName: scene.name ?? null
    };
  }


  // Snapshot the primary canvas layer (background + tiles + drawings + tokens)
  // without fog/vision. PrimaryCanvasGroup is a CachedContainer whose internal
  // texture is screen-sized — we build a temporary export container instead.
  const renderer = canvas.app.renderer;
  const primary = canvas.primary;
  if (!primary) {
    return {
      error: "primary_unavailable",
      sceneId: scene.id,
      sceneName: scene.name
    };
  }
  const renderW = Math.max(1, pxW);
  const renderH = Math.max(1, pxH);

  const dimInfo = canvas.dimensions ?? null;
  let debug = {
    bridgeVersion: MODULE_VERSION,
    fullScene,
    exportRender: true,
    cropRect: rectToStr(rect),
    sceneRect: rectToStr(dimInfo?.sceneRect),
    canvasRect: rectToStr(dimInfo?.rect),
    scenePixelSize: `${scenePxW}x${scenePxH}`,
    sceneDocSize: `${scene.width ?? 0}x${scene.height ?? 0}`,
    centerGrid: `${reportCenterI},${reportCenterJ}`,
    renderSize: `${renderW}x${renderH}`,
    screenSize: `${renderer.screen.width}x${renderer.screen.height}`,
    ...collectPrimaryLayerDebug(primary)
  };

  let imageBase64 = "";
  let offScreenRT = null;
  let exportRoot = null;
  let extractedW = 0;
  let extractedH = 0;
  let outputW = 0;
  let outputH = 0;
  try {
    exportRoot = buildViewportExportContainer(
      primary,
      rect,
      policy.filterTokens ? (id) => visibleTokenIds.has(id) : null
    );
    debug.exportChildCount = exportRoot.children.length;
    canvas.primary.update?.();

    offScreenRT = PIXI.RenderTexture.create({
      width: renderW,
      height: renderH,
      resolution: 1
    });

    // Off-screen render — does NOT swap the on-screen framebuffer.
    renderer.render(exportRoot, { renderTexture: offScreenRT, clear: true });

    const extracted = renderer.extract.canvas(offScreenRT);
    extractedW = extracted?.width ?? 0;
    extractedH = extracted?.height ?? 0;

    let outCanvas = extracted;
    const longSide = Math.max(extracted.width, extracted.height);
    if (longSide > maxLongSidePx) {
      const scale = maxLongSidePx / longSide;
      const tmp = document.createElement("canvas");
      tmp.width = Math.max(1, Math.round(extracted.width * scale));
      tmp.height = Math.max(1, Math.round(extracted.height * scale));
      tmp.getContext("2d").drawImage(extracted, 0, 0, tmp.width, tmp.height);
      outCanvas = tmp;
    }
    outputW = outCanvas.width;
    outputH = outCanvas.height;

    Object.assign(debug, analyzeViewportCanvas(outCanvas));
    debug.extractedSize = `${extractedW}x${extractedH}`;
    debug.outputSize = `${outputW}x${outputH}`;
    debug.jpegBytes = 0; // filled after encode

    const dataUrl = outCanvas.toDataURL(mimeType, quality);
    const commaIdx = dataUrl.indexOf(",");
    imageBase64 = commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl;
    debug.jpegBytes = imageBase64.length;
  } catch (err) {
    debug.renderError = String(err?.message ?? err);
    console.error(`${VIEWPORT_LOG_PREFIX} render failed`, err);
    logViewportSnapshot(debug);
    return { error: "render_failed", debug };
  } finally {
    if (exportRoot) exportRoot.destroy({ children: true, texture: false, baseTexture: false });
    if (offScreenRT) offScreenRT.destroy(true);
  }

  const ownTokenDocs = tokenDocumentsForActorOnScene(actor, scene);
  const ownTokenDoc = ownTokenDocs[0] ?? null;
  const ownTokenId = ownTokenDoc?.id ?? null;
  const ownPos = ownTokenDoc ? { x: ownTokenDoc.x, y: ownTokenDoc.y } : null;
  const userTargetIds = userTargetIdSet(user);

  const tokens = [];
  const tokenList = scene.tokens?.contents ?? [...(scene.tokens?.values?.() ?? [])];
  for (const td of tokenList) {
    if (td.hidden) continue;
    if (!includeTokenDoc(td)) continue;
    const tw = (td.width ?? 1) * sizeX;
    const th = (td.height ?? 1) * sizeY;
    if (td.x + tw < rect.x) continue;
    if (td.x > rect.x + rect.width) continue;
    if (td.y + th < rect.y) continue;
    if (td.y > rect.y + rect.height) continue;

    const off = grid.getOffset({ x: td.x, y: td.y });
    let distanceFt = null;
    if (td.id === ownTokenId) {
      distanceFt = 0;
    } else if (ownPos) {
      const pathDist = canvas.grid.measurePath([ownPos, { x: td.x, y: td.y }]).distance;
      distanceFt = typeof pathDist === "number" ? Math.round(pathDist) : null;
    }

    const disp = td.disposition;
    let side = "neutral";
    if (td.id === ownTokenId) side = "self";
    else if (disp === CONST.TOKEN_DISPOSITIONS.FRIENDLY) side = "friendly";
    else if (disp === CONST.TOKEN_DISPOSITIONS.HOSTILE) side = "hostile";

    tokens.push({
      tokenId: td.id,
      name: td.name ?? "Unknown",
      side,
      gridI: off.i,
      gridJ: off.j,
      xInCrop: Math.round(td.x - rect.x),
      yInCrop: Math.round(td.y - rect.y),
      widthCells: Number(td.width ?? 1),
      heightCells: Number(td.height ?? 1),
      disposition: typeof disp === "number" ? disp : 0,
      isSelf: td.id === ownTokenId,
      isTarget: userTargetIds.has(td.id),
      distanceFt,
      elevation: td.elevation ?? 0
    });
  }

  let template = null;
  if (activeTemplateId) {
    const tdoc = scene.templates?.get(activeTemplateId) ?? null;
    if (tdoc) {
      template = templateDocToClient(tdoc, rect.x, rect.y, grid);
    }
  }

  logViewportSnapshot(debug);

  return {
    imageBase64,
    mimeType,
    originX: rect.x,
    originY: rect.y,
    widthPx: rect.width,
    heightPx: rect.height,
    gridSize: grid.size,
    gridSizeX: sizeX,
    gridSizeY: sizeY,
    gridType,
    gridTypeId,
    scenePixelWidth: scene.width ?? canvas.dimensions?.sceneWidth ?? 0,
    scenePixelHeight: scene.height ?? canvas.dimensions?.sceneHeight ?? 0,
    centerGridI: reportCenterI,
    centerGridJ: reportCenterJ,
    widthCells: outWidthCells,
    heightCells: outHeightCells,
    tokens,
    template,
    debug
  };
}

